// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    Accepter accepter;

    function setUp() public {
        c = new XBORNID();
        accepter = new Accepter();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max);
        c.transferOwnership(address(accepter));
        vm.deal(address(c), amount);
        vm.prank(address(accepter));
        c.withdraw();
        assertTrue(address(c).balance == 0);
    }
}

contract Accepter {
    receive() external payable {}
}
